INSERT INTO use_record (
    uuid, device_id, project_id, engineering_id, task_id, user_id,
    use_start_time, use_end_time, note, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{deviceId}, #{projectId}, #{engineeringId}, #{taskId}, #{userId},
             #{useStartTime}, #{useEndTime}, #{note}, #{isDel}
         )
